import{_ as o,o as t,c as a,a0 as c}from"./chunks/framework.Obqu-B4P.js";const h=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),n={name:"explanation/concepts.md"};function r(s,e,d,i,l,u){return t(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>The vocabulary of the cuora secrets broker — each term defined once.</p><h2 id="refs-and-values" tabindex="-1">Refs and values <a class="header-anchor" href="#refs-and-values" aria-label="Permalink to &quot;Refs and values&quot;">​</a></h2><ul><li><strong><code>cuora://</code> ref</strong> — the only way a secret is named in code and config: <code>cuora://&lt;ns&gt;/&lt;name&gt;</code>, optionally env-pinned (<code>cuora://prod/ns/name</code>). Never a value.</li><li><strong><code>Secret</code></strong> — the redacting newtype every resolved value passes through: no <code>Display</code>/<code>Debug</code> of plaintext, <code>.expose()</code> is the only way out, memory is <code>Zeroizing</code>-scrubbed on drop.</li><li><strong>Env</strong> — the routing axis (<code>dev</code>/<code>staging</code>/<code>prod</code> + customs). The same ref holds different values per env; <code>cuora://prod/…</code> pins one.</li><li><strong>Actor</strong> — who performed an op (<code>CUORA_ACTOR</code>, <code>--actor</code>). Self-claimed attribution, not identity — enforcement is peregrin&#39;s.</li></ul><h2 id="vaults-and-identity" tabindex="-1">Vaults and identity <a class="header-anchor" href="#vaults-and-identity" aria-label="Permalink to &quot;Vaults and identity&quot;">​</a></h2><ul><li><strong>Vault</strong> — a readable secret store behind the <code>cuora-vault</code> port: <code>get</code>/<code>put</code>/<code>list</code>/<code>rotate</code>/<code>rm</code>, per-env variants, ciphertext-only at rest. Impls: <code>age</code> (local file), <code>cf</code> (self-hosted Worker + D1), <code>cached</code> (read-through local mirror).</li><li><strong>Identity</strong> — the one X25519 age keypair that unlocks every vault. Held by an <code>cuora-identity</code> impl: session keyring (default, fails closed) or <code>identity.txt</code> keyfile (headless/CI opt-in).</li><li><strong>Recipient</strong> — a public <code>age1…</code> key a vault encrypts to; <code>[vaults.*].recipients</code> adds team keys without sharing the private one.</li><li><strong><code>token_env</code></strong> — config names the <em>env var</em> carrying a credential; the value only ever lives in process env.</li></ul><h2 id="surfaces-and-packs" tabindex="-1">Surfaces and packs <a class="header-anchor" href="#surfaces-and-packs" aria-label="Permalink to &quot;Surfaces and packs&quot;">​</a></h2><ul><li><strong><code>cuora run</code></strong> — the agent path: resolves <code>[secrets]</code> (+ <code>-s</code> pairs), injects values as env vars into the child only, exits with the child&#39;s code. Values never enter the spawner&#39;s context.</li><li><strong><code>cuora env</code></strong> — the human path: <code>export VAR=&#39;…&#39;</code> lines for <code>eval</code>. Prints plaintext — that&#39;s why agents use <code>run</code>.</li><li><strong><code>[secrets]</code></strong> — the injectable surface: the <code>VAR = &quot;cuora://…&quot;</code> table bounding what <code>run</code>/<code>env</code> may materialize. Least privilege.</li><li><strong><code>[guardrails]</code></strong> — advisory allow/deny op table honored before any vault touch. Accident prevention, not enforcement.</li><li><strong>Audit event</strong> — one ndjson line on stderr per op (actor, op, ref, env, outcome, timestamp); OTLP span when an endpoint is configured.</li><li><strong>Sealed pack</strong> — a tamias <code>type: secrets</code> package whose payload is age ciphertext only; tamias carries it opaquely, cuora opens it consumer-side via <code>cuora://&lt;pack&gt;/&lt;secret&gt;</code> refs.</li><li><strong>Deploy sink</strong> — a write-only push target (<code>[deploy.*]</code>, e.g. CF Secrets Store). Plaintext crosses once, at push; never a source.</li><li><strong><code>cuora serve</code></strong> — the ndjson JSON-RPC surface orchestrators embed; <code>[serve.pdp]</code> is the exec-driven policy-decision consult.</li></ul>',8)])])}const g=o(n,[["render",r]]);export{h as __pageData,g as default};
